import logging
from enum import IntEnum
from time import sleep

from audio_server.drivers.interfaces.gpio import GPIO_OUTPUT
from audio_server.drivers.interfaces.i2c import I2CPeripheral

logger = logging.getLogger(__name__)

SLEEP_TIME = 0.5


class _Register(IntEnum):
    SOFT_RESET = 0xF890
    PLL_ENABLE = 0xF003
    PLL_CTRL0 = 0xF000
    PLL_CTRL1 = 0xF001
    PLL_CLK_SRC = 0xF002
    MCLK_OUT = 0xF005
    CLK_GEN1_N = 0xF021
    POWER_ENABLE0 = 0xF050
    POWER_ENABLE1 = 0xF051
    SOUT_SOURCE0 = 0xF180
    SERIAL_BYTE_0_0 = 0xF200

    @staticmethod
    def SERIAL_BYTE(i: int, j: int):
        assert 0 <= i <= 7 and 0 <= j <= 1
        return _Register.SERIAL_BYTE_0_0 + i * 4 + j

    PROGRAM_DATA = 0xC000
    DM0 = 0x0000
    DM1 = 0x6000
    HIBERNATE = 0xF400
    START_PULSE = 0xF401
    START_CORE = 0xF402
    KILL_CORE = 0xF403
    START_ADDRESS = 0xF404
    CORE_STATUS = 0xF405

    # SIGMASTUDIO
    SIGMA_PARAM_VALUE = 0x6000
    SIGMA_PARAM_ADDRESS = 0x6005


def register_width(addr: int):
    if addr >= 0x0000 and addr <= 0x4FFF:
        return 4
    if addr >= 0x6000 and addr <= 0xAFFF:
        return 4
    if addr >= 0xC000 and addr <= 0xDFFF:
        return 4
    return 2


class ADAU1452:
    def __init__(self, i2c: I2CPeripheral, gpio_enable: GPIO_OUTPUT):
        self.gpio_enable = gpio_enable
        self.i2c = i2c

    def write_reg(self, addr: int | _Register, data: str) -> None:
        data_bytes = bytes.fromhex(data)

        self.i2c.write(addr, data_bytes, register_width_bytes=register_width(addr))

    def read_reg(self, addr: int, length: int = 2) -> bytearray:
        return bytearray(self.i2c.read(addr, length))

    def read_reg_int(self, addr: int, length: int = 2) -> int:
        return int.from_bytes(self.read_reg(addr, length), "big")

    def check(self, addr: _Register, expected: str, length: int = 2) -> None:
        val = self.read_reg(addr, length)
        expected_bytes = bytes.fromhex(expected)
        if val != expected_bytes:
            raise Exception(
                f"Expected {expected_bytes.hex()} at {addr.name}, got {val.hex()}"
            )

    def set_sout_source(self, index: int, source: str) -> None:
        assert 0 <= index <= 23
        self.write_reg(_Register.SOUT_SOURCE0 + index, source)

    def set_serial_byte(self, index: int, data: str) -> None:
        assert 0 <= index <= 7
        self.write_reg(_Register.SERIAL_BYTE(index, 0), data)

    @staticmethod
    def _float_to_bytes(value: float) -> bytes:
        """Convert float to 8.24 fixed-point format (4 bytes).

        The ADAU1452 uses 8.24 fixed-point format where:
        - 8 bits for integer part (sign + 7 integer bits)
        - 24 bits for fractional part
        - Scale factor: 2^24 = 16777216

        Args:
            value: Float value to convert (range: -128.0 to +127.999999940)

        Returns:
            4 bytes in big-endian format
        """
        # Convert float to 8.24 fixed-point integer
        fixed_point = int(value * (2**24))

        # Convert to 4 bytes (big-endian, signed)
        return fixed_point.to_bytes(4, byteorder="big", signed=True)

    @staticmethod
    def _bytes_to_float(data: bytes) -> float:
        """Convert 8.24 fixed-point format (4 bytes) to float.

        The ADAU1452 uses 8.24 fixed-point format where:
        - 8 bits for integer part (sign + 7 integer bits)
        - 24 bits for fractional part
        - Scale factor: 2^24 = 16777216

        Args:
            data: 4 bytes in big-endian format

        Returns:
            Float value
        """
        # Convert 4 bytes to signed integer
        fixed_point = int.from_bytes(data, byteorder="big", signed=True)

        # Convert to float by dividing by scale factor
        return fixed_point / (2**24)

    def read_float_parameter(self, addr: int) -> float:
        """Read a float parameter from DSP memory.

        Args:
            addr: Parameter address in DSP memory (e.g., 0x0377)

        Returns:
            Float value in 8.24 fixed-point format
        """
        # Read 4 bytes directly from the parameter address
        data = bytes(self.read_reg(addr, length=4))
        return self._bytes_to_float(data)

    def set_float_parameter(self, addr: int, value: float) -> None:
        # 2025-11-14T16:01:13.558973 192.168.1.113:51640 WRITE addr=0x6000 len=4 data=0019999a
        # 2025-11-14T16:01:13.560586 192.168.1.113:51640 WRITE addr=0x6005 len=8 data=0000037700000001

        assert 0 <= value <= 128
        hex_val = self._float_to_bytes(value).hex()
        self.write_reg(_Register.SIGMA_PARAM_VALUE, hex_val)

        _MAGIC = b"\x00\x00\x00\x01"
        addr_bytes = addr.to_bytes(4, "big") + _MAGIC
        self.write_reg(_Register.SIGMA_PARAM_ADDRESS, addr_bytes.hex())

        # 2025-11-14T16:05:07.767365 192.168.1.113:51640 WRITE addr=0x0376 len=4 data=00000000
        # 2025-11-14T16:05:10.104636 192.168.1.113:51640 WRITE addr=0x0376 len=4 data=00000001

        # Mute & Unmute 0x376
        # for some reason mute works differently than float / volume slider
        # SafeloadWrite vs BlockWrite
        pass

    def set_bool_parameter(self, addr: int, value: bool):
        # TODO for some reason 4 bytes instead of 2
        raise NotImplementedError("Not implemented")
        self.write_reg(addr, "00000001" if value else "00000000")

    def enable(self):
        self.gpio_enable.deactivate()
        sleep(1)
        self.gpio_enable.activate()
        sleep(1)

        # Soft reset
        self.write_reg(_Register.SOFT_RESET, "0000")
        self.write_reg(_Register.SOFT_RESET, "0001")
        sleep(SLEEP_TIME)

        # Hibernate
        self.write_reg(_Register.HIBERNATE, "0000")
        self.write_reg(_Register.HIBERNATE, "0001")
        sleep(SLEEP_TIME)

        self.check(_Register.HIBERNATE, "0001")

        # Kill Core
        self.write_reg(_Register.KILL_CORE, "0000")
        self.write_reg(_Register.KILL_CORE, "0001")

        # PLL Enable
        self.write_reg(_Register.PLL_ENABLE, "0000")
        self.write_reg(_Register.PLL_CTRL0, "0060")
        self.write_reg(_Register.PLL_CTRL1, "0002")
        self.write_reg(_Register.PLL_CLK_SRC, "0001")
        self.write_reg(_Register.MCLK_OUT, "0005")
        self.write_reg(_Register.PLL_ENABLE, "0001")
        sleep(SLEEP_TIME)

        # Power Enable
        self.write_reg(_Register.POWER_ENABLE0, "1fff")
        self.write_reg(_Register.POWER_ENABLE1, "001f")

        # Set clk (96KHz)
        self.write_reg(_Register.CLK_GEN1_N, "0002")

        # SOUT_SOURCE0-23
        for i in range(0, 24):
            self.set_sout_source(i, "0002")

        # Serial Byte 0_0 -> 7_0
        for i in range(7):
            if i == 0:
                continue
            if i in [1, 2, 5, 6]:
                self.set_serial_byte(i, "9002")
            if i in [3, 7]:
                self.set_serial_byte(i, "9000")

        # Program Data
        self.write_reg(
            _Register.PROGRAM_DATA,
            "",
        )
        # DM0
        self.write_reg(
            _Register.DM0,
            "",
        )
        # DM1
        self.write_reg(
            _Register.DM1,
            "",
        )
        # Kill Core
        self.write_reg(_Register.KILL_CORE, "0000")
        # Start Address
        self.write_reg(_Register.START_ADDRESS, "0000")
        # Start Pulse
        self.write_reg(_Register.START_PULSE, "0002")
        # Start Core
        self.write_reg(_Register.START_CORE, "0000")
        self.write_reg(_Register.START_CORE, "0001")
        sleep(SLEEP_TIME)

        # Hibernate
        self.write_reg(_Register.HIBERNATE, "0000")

        # READ addr=0xF405 len=2 data=0000

        self.check(_Register.HIBERNATE, "0000")
        self.check(_Register.KILL_CORE, "0000")
